    /**
     * 按周生成报表
     * @param theDate
     * @param theMonth
     */
    WateringSchedulePage.prototype.generateWeekReport = function (theDate, theMonth) {
        var me = this;
        //当前日期
        var curDate = new Date();
        //头5个月，后一个月
        var designDate = theDate;
        var designYear = designDate.getFullYear();
        var designMonth = designDate.getMonth() + 1;
        var minMonth = designMonth - 5;
        var maxMonth = designMonth + 1;
        var minDate;
        if (minMonth < 1) {
            minDate = new Date(designYear - 1, 12 + minMonth - 1, 1);
        }
        else {
            minDate = new Date(designYear, minMonth - 1, 1);
        }
        var maxDate;
        if (maxMonth > 12) {
            maxDate = new Date(designYear + 1, maxMonth - 12, 1);
        }
        else {
            maxDate = new Date(designYear, maxMonth, 1);
        }
        if (!theMonth) {
            //未指定月份，则用当前传入的日期
            theMonth = designYear + me.nativeService.padStart2(designMonth.toString(), 2, '0');
        }
        var monthNames = [me.translate.get("month.january")["value"], me.translate.get("month.february")["value"],
            me.translate.get("month.march")["value"], me.translate.get("month.april")["value"],
            me.translate.get("month.may")["value"], me.translate.get("month.june")["value"],
            me.translate.get("month.july")["value"], me.translate.get("month.august")["value"],
            me.translate.get("month.september")["value"], me.translate.get("month.october")["value"],
            me.translate.get("month.november")["value"], me.translate.get("month.december")["value"]];
        //maxDate>有效日期>=minDate
        var findMonthText = '';
        var findYear;
        var findMonth;
        var selectMonths = [];
        for (var i = 0; i < 7; i++) {
            var tmpYear = minDate.getFullYear();
            var tmpMonth = minDate.getMonth() + i + 1;
            if (tmpMonth > 12) {
                tmpYear++;
                tmpMonth -= 12;
            }
            var v = tmpYear + me.nativeService.padStart2(tmpMonth.toString(), 2, '0');
            var t = monthNames[tmpMonth - 1] + " " + tmpYear;
            selectMonths.push({ value: v, text: t });
            if (v == theMonth) {
                findMonthText = t;
                findYear = tmpYear;
                findMonth = tmpMonth;
            }
        }
        //未找到，则退出生成
        if (!findMonthText)
            return;
        me.currentSelectMonthByWeek = theMonth;
        //指定当前选择的月份
        $('#spnMonthSelectByWeek>span.month-text').text(findMonthText);
        //填充月份选择菜单
        var $menu = $('div.select-month-menu-byweek');
        //清空菜单
        if ($menu.length < 1)
            $menu = $('<div class="select-month-menu select-month-menu-byweek month-set"></div>').appendTo('selector-wateringSchedule');
        else
            $menu.html('');
        //填充菜旱
        for (var i_1 = 0; i_1 < selectMonths.length; i_1++) {
            $('<div class="item" month="' + selectMonths[i_1].value + '">' + selectMonths[i_1].text + '</div>').appendTo($menu).click(function () {
                me.doSelectMonthByWeek(this);
            });
        }
        //隐藏菜单
        $menu.hide();
        //计算要填充的天数
        //起始日期
        var startDate = new Date(findYear, findMonth - 1, 1);
        //终止日期
        var endYear = findYear;
        var endMonth = findMonth + 1;
        if (endMonth > 12) {
            endYear++;
            endMonth = endMonth - 12;
        }
        var endDate = new Date(endYear, endMonth - 1, 1);
        //需填充的天数
        var days = [];
        var startWeek = startDate.getDay();
        var loop = (startWeek == 0 ? 7 : startWeek);
        //向前找星期一
        for (var idx = loop; idx > 0; idx--) {
            var tmpDate = new Date(startDate);
            tmpDate.setTime(tmpDate.getTime() - idx * 24 * 60 * 60 * 1000);
            days.push({
                isIn: false,
                isMonday: tmpDate.getDay() == 1,
                isSunday: tmpDate.getDay() == 0,
                date: tmpDate
            });
        }
        //在该月份内的时间
        var dIdx = 0;
        while (true) {
            var tmpDate_1 = new Date(startDate);
            tmpDate_1.setTime(tmpDate_1.getTime() + dIdx * 24 * 60 * 60 * 1000);
            if (tmpDate_1 >= endDate)
                break;
            days.push({
                isIn: true,
                isMonday: tmpDate_1.getDay() == 1,
                isSunday: tmpDate_1.getDay() == 0,
                date: tmpDate_1
            });
            dIdx++;
        }
        //向后找星期一
        for (var idx_1 = 0; idx_1 < 7; idx_1++) {
            var tmpDate_2 = new Date(endDate);
            tmpDate_2.setTime(tmpDate_2.getTime() + idx_1 * 24 * 60 * 60 * 1000);
            var isMonday = tmpDate_2.getDay() == 1;
            days.push({
                isIn: false,
                isMonday: isMonday,
                isSunday: tmpDate_2.getDay() == 0,
                date: tmpDate_2
            });
            if (isMonday)
                break;
        }
        //清空表
        $('#tbWeekReport').html('');
        //计算表格宽度与列宽度
        var colTotal = days.length - 2;
        var srWidth = $('#plWeekContainer').width();
        var spanOffset = srWidth % 7;
        var colWidth = (srWidth - spanOffset) / 7;
        var tbWidth = 0;
        var weekTotal = colTotal / 7;
        //当前滚动的页宽度
        var pageWidth = 7 * colWidth + spanOffset;
        var weekDays = me.commandFactory.getWeekDays("weekDaysShort");
        var weekNames = [];
        weekDays.forEach(function (v) {
            weekNames.push(v.day);
        });
        // var weekNames=[me.translate.get("weekDays.sunday")["value"],me.translate.get("weekDays.monday")["value"],
        //   me.translate.get("weekDays.tuesday")["value"],me.translate.get("weekDays.wednesday")["value"],
        //   me.translate.get("weekDays.thursday")["value"],me.translate.get("weekDays.friday")["value"],
        //   me.translate.get("weekDays.saturday")["value"]];
        //创建四个表格行
        var $sumTr = $('<ul class="sum" style="border-bottom:0.5px solid black;"></ul>').appendTo('#tbWeekReport');
        var $weekTr = $('<ul class="week"></ul>').appendTo('#tbWeekReport');
        var $dateTr = $('<ul class="date"></ul>').appendTo('#tbWeekReport');
        var $dataTr = $('<ul class="data"></ul>').appendTo('#tbWeekReport');
        //当前月
        var isSampleMonth = curDate.getFullYear() == findYear && (curDate.getMonth() + 1) == findMonth;
        var resetScrollLeft = -1;
        //重新填充表
        for (var i_2 = 0; i_2 < weekTotal; i_2++) {
            //每周填充
            //统计合并列的宽度
            var spanSumTd = 0;
            for (var j = 0; j < 7; j++) {
                //对应数据的位置
                var dayPos = i_2 * 7 + j + 1;
                //选择的为当前月
                if (isSampleMonth && resetScrollLeft < 0) {
                    if (days[dayPos].date.getDate() == curDate.getDate()) {
                        //找到了该日期
                        resetScrollLeft = i_2 * pageWidth;
                    }
                }
                //单列的宽度
                var w = colWidth + (j < spanOffset ? 1 : 0);
                //region 单元格
                //debugger
                //region 填充周
                var weekDayIndx = weekNames.length - 1;
                if (days[dayPos].date.getDay() > 0)
                    weekDayIndx = days[dayPos].date.getDay() - 1;
                $('<li></li>').appendTo($weekTr).html(weekNames[weekDayIndx]).width(w);
                //endregion
                //region 日期
                $('<li></li>').appendTo($dateTr).width(w).text(days[dayPos].isIn ? days[dayPos].date.getDate() : "");
                //endregion
                //region 填充数据
                $('<li></li>').appendTo($dataTr).width(w - 1.25).attr('date', days[dayPos].date.getFullYear() + '-' + me.nativeService.padStart2((days[dayPos].date.getMonth() + 1).toString(), 2, '0') + '-' + me.nativeService.padStart2(days[dayPos].date.getDate().toString(), 2, '0'));
                //endregion
                //region 填充统计
                var txt = '';
                switch (j) {
                    case 0:
                        {
                            if (i_2 == 0) {
                                txt = me.nativeService.padStart2(days[0].date.getDate().toString(), 2, 0);
                            }
                            else {
                                txt = me.nativeService.padStart2(days[dayPos - 1].date.getDate().toString(), 2, 0);
                            }
                            //第一列
                            $('<li></li>').appendTo($sumTr).width(w).css("text-align", "left").text(txt);
                        }
                        break;
                    case 5:
                        {
                            //取周一与周日的日期
                            txt = me.nativeService.padStart2(days[dayPos - 5].date.getDate().toString(), 2, 0) + '-' + me.nativeService.padStart2(days[dayPos + 1].date.getDate().toString(), 2, 0);
                            //合并列
                            $('<li></li>').appendTo($sumTr).width(spanSumTd + w).text(txt);
                        }
                        break;
                    case 6:
                        {
                            if (i_2 == weekTotal - 1) {
                                txt = me.nativeService.padStart2(days[days.length - 1].date.getDate().toString(), 2, 0);
                            }
                            else {
                                txt = me.nativeService.padStart2(days[dayPos + 1].date.getDate().toString(), 2, 0);
                            }
                            //最后一列
                            $('<li></li>').appendTo($sumTr).width(w).css("text-align", "right").text(txt);
                        }
                        break;
                    default:
                        spanSumTd += w;
                        break;
                }
                //endregion
                //endregion
                tbWidth += w;
            }
        }
        //设置滚动单元的宽度
        $('#plWeekReport').width(pageWidth);
        //设置表格宽度
        $('#tbWeekReport').width(tbWidth);
        //触屏翻页查看每周
        $('#tbWeekReport').on('touchstart', function (evt) {
            $(this).attr('startX', evt.originalEvent.targetTouches[0].pageX).attr('leftX', Math.round($('#plWeekReport').scrollLeft()));
        }).on('touchmove', function (evt) {
            //distance >0 向右  distance<0 向左
            var distance = evt.originalEvent.targetTouches[0].pageX - parseFloat($(this).attr('startX'));
            $('#plWeekReport').scrollLeft(parseInt($(this).attr('leftX')) - distance);
        }).on('touchend', function (evt) {
            var distance = evt.originalEvent.changedTouches[0].pageX - parseFloat($(this).attr('startX'));
            if (Math.abs(distance) > 50) {
                //只有移动了50个像素才滚页
                //distance >0 向右  distance<0 向左
                $('#plWeekReport').scrollLeft(parseInt($(this).attr('leftX')) + (distance > 0 ? -1 : 1) * pageWidth);
            }
            else {
                //退回原位
                $('#plWeekReport').scrollLeft(parseInt($(this).attr('leftX')));
            }
            //阻止系统默认事件
            evt.preventDefault();
        });
        //重置滚动位置
        $('#plWeekReport').scrollLeft(resetScrollLeft < 0 ? 0 : resetScrollLeft);
        //请求浇水记录
        me.requstHistoryByWeek(startDate, curDate);
        //请求计划表
        me.requestScheduleByWeek(curDate, endDate);
    };
