    /**
     * 请求浇水记录完成回调(按周)
     * @param json
     */
    WateringSchedulePage.prototype.onRequstHistoryByWeekComplete = function (json, zone, strStartDate, strEndDate, handle) {
        var me = handle;
        try {
            if (json.result > 0) {
                for (var i = 0; i < json.rows.length; i++) {
                    //新版单口不显示站点2
                    if (json.rows[i].zoneName && json.rows[i].zoneName == "zone2" && me.thisVersion > 3 && me.thisVersionType == '1C') {
                        break;
                    }
                    if (json.rows[i].zoneName && json.rows[i].createTime) {
                        var strDate = json.rows[i].createTime.replace(/^(.*)\s+.*$/g, "$1");
                        $('#tbWeekReport ul.data>li[date="' + strDate + '"]').each(function (idx, cel) {
                            var $zone = $('div.' + json.rows[i].zoneName, cel);
                            if ($zone.length < 1) {
                                var zoneName = null;
                                if (json.rows[i].zoneName == 'zone1') {
                                    zoneName = me.translate.get("twoExport.twoSchedule.zone1")["value"];
                                }
                                else if (json.rows[i].zoneName == 'zone2') {
                                    zoneName = me.translate.get("twoExport.twoSchedule.zone2")["value"];
                                }
                                $zone = $('<div class="' + json.rows[i].zoneName + ' zone-cel"></div>').appendTo(cel);
                                //$zone.append('<span class="zone-title">站点'+json.rows[i].zoneName.replace(/^.*(\d+)$/g,"$1")+'</span><br/>');
                                $zone.append('<span class="zone-title">' + zoneName + '</span><br/>');
                            }
                            //组装显示数据
                            var showCreateTime = "";
                            var createTime = new Date(json.rows[i].createTime);
                            showCreateTime = me.commandFactory.getTimePatch(createTime.getHours()) + ":" + me.commandFactory.getTimePatch(createTime.getMinutes());
                            if (__WEBPACK_IMPORTED_MODULE_5__app_appconfig__["a" /* AppConfig */].timeFormat == 12) {
                                showCreateTime = createTime.getHours() + ":" + me.commandFactory.getTimePatch(createTime.getMinutes());
                                if (createTime.getHours() > 12 && createTime.getHours() < 24) {
                                    showCreateTime = (createTime.getHours() - 12) + ":" + me.commandFactory.getTimePatch(createTime.getMinutes());
                                }
                                if (createTime.getHours() == 0) {
                                    showCreateTime = (createTime.getHours() + 12) + ":" + me.commandFactory.getTimePatch(createTime.getMinutes());
                                }
                                if (createTime.getHours() >= 0 && createTime.getHours() < 12) {
                                    showCreateTime += " " + me.translate.get("common.am")["value"];
                                }
                                else {
                                    showCreateTime += " " + me.translate.get("common.pm")["value"];
                                }
                            }
                            // if(showCreateTime)showCreateTime+="<br/>";
                            var showLog = "";
                            var logary = json.rows[i].log ? json.rows[i].log.toString().split(":") : [];
                            if (logary.length >= 3) {
                                if ((parseInt(logary[0]) * 60 + parseInt(logary[1])) > 0) {
                                    showLog = (parseInt(logary[0]) * 60 + parseInt(logary[1])) + " " + me.translate.get("common.min")["value"] + " ";
                                }
                                if (parseInt(logary[2]) > 0) {
                                    showLog += parseInt(logary[2]) + " " + me.translate.get("common.sec")["value"];
                                }
                            }
                            //if(showLog)showLog+="<br/>";
                            //$('<span class="zone-history"></span>').appendTo($zone).html(showCreateTime+showLog);
                            var txt = "<span style='display: block;font-size: 0.5rem'>" + showCreateTime + "</span><span style='display: block;font-size: 0.5rem'>" + showLog + "</span><br>";
                            $('<div class="zone-history"></div>').appendTo($zone).html(txt);
                            //$('<span class="zone-history"></span>').appendTo($zone).html(json.rows[i].createTime.replace(/^.*\s+(.*)$/g,"$1")+(json.rows[i].log?"<br/>"+json.rows[i].log:""));
                        });
                    }
                }
            }
        }
        catch (e) {
        }
    };
