    HomeBttsPage.prototype.isFirstStart = function (address, fun) {
        var self = this;
        var local_start_count = {
            SecondStartCount: 0,
            SecondLogin: false,
            FirstStartCount: 0,
            FirstLogin: false
        };
        if (localStorage.getItem("local_start_count")) {
            var local_start_count_1 = JSON.parse(localStorage.getItem("local_start_count"));
            if (local_start_count_1.SecondLogin) {
                fun();
            }
        }
        local_start_count.SecondStartCount += 1;
        localStorage.setItem("local_start_count", JSON.stringify(local_start_count));
        if (__WEBPACK_IMPORTED_MODULE_8__app_appconfig__["a" /* AppConfig */].isDebug) {
            var Second_81 = self.commandFactory.getCommand(__WEBPACK_IMPORTED_MODULE_6__util_CommandFactory__["c" /* ProtocolType */].Second_81);
            Second_81.password = Second_81.password.replace(/(\u0000)+/, "").toString().trim();
            //第一次登陆并且设置了密码的情况下需要登陆操作
            if (Second_81.password && !local_start_count.SecondLogin) {
                self.goLogin(address);
            }
            else {
                fun();
            }
            self.goLogin(address);
        }
        else {
            self.commandFactory.readRemote(__WEBPACK_IMPORTED_MODULE_6__util_CommandFactory__["c" /* ProtocolType */].Second_81, function (suc) {
                var Second_81 = suc;
                Second_81.password = Second_81.password.replace(/(\u0000)+/, "").toString().trim();
                self.commandFactory.editCommand2(Second_81);
                //第一次登陆并且设置了密码的情况下需要登陆操作
                if (Second_81.password && !local_start_count.SecondLogin) {
                    self.goLogin(address);
                }
                else {
                    fun();
                }
            }, null, __WEBPACK_IMPORTED_MODULE_8__app_appconfig__["a" /* AppConfig */].runInfo["isOnline"]);
        }
    };
