    TwoSchedulePage.prototype.InsertDhash = function (States, createTime) {
        if (States === void 0) { States = 0; }
        if (createTime === void 0) { createTime = null; }
        var mac = null;
        var tempDevice = JSON.parse(localStorage.getItem("local_device_list"));
        for (var i = 0; i < tempDevice.length; i++) {
            if (tempDevice[i]["connected"] == true) {
                mac = tempDevice[i]["address"];
                break;
            }
        }
        DHash = JSON.parse(localStorage.getItem("DHash"));
        var time = new Date(createTime);
        if (DHash) {
            var item = DHash.find(function (itemDHash) {
                return (itemDHash.time == time.toLocaleDateString() && itemDHash.mac == mac && itemDHash.states >= 0);
            });
            if (item == undefined) {
                DHash.push({
                    time: time.toLocaleDateString(),
                    mac: mac,
                    states: States
                });
            }
        }
        else {
            DHash = [];
            DHash.push({
                time: time.toLocaleDateString(),
                mac: mac,
                states: States
            });
        }
        localStorage.setItem("DHash", JSON.stringify(DHash));
    };
    TwoSchedulePage.prototype.updateDeviceConnectState = function () {
        var me = this;
        var tempDevice = [];
        if (localStorage.getItem("local_device_list")) {
            tempDevice = JSON.parse(localStorage.getItem("local_device_list"));
            var _loop_1 = function (i) {
                if (tempDevice[i]["connected"] == true) {
                    if (__WEBPACK_IMPORTED_MODULE_8__app_appconfig__["a" /* AppConfig */].isDebug) {
                        tempDevice[i]["firmware"] = __WEBPACK_IMPORTED_MODULE_8__app_appconfig__["a" /* AppConfig */].firmwareVersion;
                        localStorage.setItem("local_device_list", JSON.stringify(tempDevice));
                        localStorage.setItem("thisversiontype", "1C"); //默认1C新版单口，2C新版双口
                        me.thisVersionType = me.connectedDevice.thisversiontype;
                    }
                    else {
                        me.platform.ready()
                            .then(function () {
                            cordova.plugins.AisBlePlugin.read("FirmwareVersion", function (info) {
                                //AppConfig.consoleLog("FirmwareVersion:" + info.version);
                                tempDevice[i]["firmware"] = info.version;
                                __WEBPACK_IMPORTED_MODULE_8__app_appconfig__["a" /* AppConfig */].firmwareVersion = info.version;
                                if (info && info.version) {
                                    localStorage.setItem("thisversion", (info.version.replace("Version ", "")).split('.')[0]);
                                    me.thisVersion = me.connectedDevice.thisversion;
                                    me.thisVersionType = me.connectedDevice.thisversiontype;
                                    if (me.thisVersion > 3)
                                        localStorage.setItem("thisversiontype", me.connectedDevice.thisversiontype);
                                }
                                else {
                                    localStorage.setItem("thisversion", "0");
                                    localStorage.setItem("thisversiontype", "1C"); //默认1C新版单口，2C新版双口
                                }
                                //localStorage.setItem("thisversion", (info.version.replace("Version ", "")).split('.')[0])
                                localStorage.setItem("local_device_list", JSON.stringify(tempDevice));
                            }, function (errMsg) {
                                // me.nativeService.showToast(errMsg);
                            });
                        });
                    }
                }
            };
            for (var i = 0; i < tempDevice.length; i++) {
                _loop_1(i);
            }
        }
    };
    TwoSchedulePage.prototype.timerList9D = function () {
        var self = this;
        //if (1 == 1) return;
        self.stopTimeList9D();
        //监控任务执行情况
        __WEBPACK_IMPORTED_MODULE_8__app_appconfig__["a" /* AppConfig */].runInfo['timer']["timelist.9d"] = setInterval(function () {
            list9D = JSON.parse(localStorage.getItem("List9D"));
            if (list9D.length < 1) {
                return;
            }
            for (var i = 0; i <= list9D.length; i++) {
                //如果有任务正在执行，退出不做任何操作
                if (list9D[i].state == 1)
                    break;
                //开始执行当前操作
                list9D[i].state = 1;
                //start
                // function send Second_90
                var Second_9D = {
                    "protocolType": "Second_9D",
                    "startTime": list9D[i].time + " 00:00:00",
                    "endTime": list9D[i].time + " 23:59:59" //查询结束时间戳
                };
                self.InsertDhash(0, list9D[i].time);
                self.commandFactory.send_2("twoSchedule", Second_9D)
                    .then(function (success) {
                    //AppConfig.consoleLog(success);
                    localStorage.setItem("List9D", JSON.stringify(list9D));
                });
                //do something
                //end
                break;
            }
        }, 1 * 1000);
    };
