    TwoSchedulePage.prototype.getNewRunTime = function (times) {
        var self = this;
        var strSecond_9C = JSON.parse(localStorage.getItem("Second_9C"));
        if (strSecond_9C) {
            var Percentage = 0;
            times = times.split(':');
            if (strSecond_9C.isGlobal == true) {
                Percentage = strSecond_9C.config[0] / 100;
            }
            else {
                var thisMonth = self.utilityService.getDateMonth(0);
                Percentage = (strSecond_9C.config[thisMonth - 1]) / 100;
            }
            var newSeconds = Percentage * (parseInt(times[0]) * 60 * 60 + parseInt(times[1]) * 60 + parseInt(times[2]));
            var hour = parseInt((newSeconds / 3600).toString());
            var min = parseInt(((newSeconds - (hour * 3600)) / 60).toString());
            var sec = parseInt((newSeconds - (hour * 3600) - (min * 60)).toString());
            return (hour < 10 ? "0" + hour.toString() : hour.toString()) + ":" + (min < 10 ? "0" + min.toString() : min.toString()) + ":" + (sec < 10 ? "0" + sec.toString() : sec.toString());
        }
        else {
        }
    };
