    //获取当天历史浇灌时间
    TwoSchedulePage.prototype.getCurDateHistory = function () {
        var self = this;
        var startTime = self.commandFactory.dateFormat(new Date(), "yyyy-MM-dd") + " 00:00:00";
        var endTime = self.commandFactory.dateFormat(new Date(), "yyyy-MM-dd") + " 23:59:59";
        this.commandFactory.remoteQueryLogByTime(startTime, endTime)
            .then(function (success) {
            var r = success; //JSON.parse(JSON.stringify(success));
            ////AppConfig.consoleLog(r);
            var minTime = 0, secTime = 0;
            var timeAry = null;
            if (r.rows.length > 0) {
                r.rows.forEach(function (row) {
                    if (self.thisVersion > 3) {
                        if (row.runTime) {
                            timeAry = row.log ? row.log.split(":") : null;
                            if (timeAry) {
                                minTime += parseInt(timeAry[0]) * 60 + parseInt(timeAry[1]);
                                secTime += parseInt(timeAry[2]);
                            }
                            timeAry = null;
                        }
                    }
                    else {
                        timeAry = row.log ? row.log.split(":") : null;
                        if (timeAry) {
                            minTime += parseInt(timeAry[0]) * 60 + parseInt(timeAry[1]);
                            secTime += parseInt(timeAry[2]);
                        }
                        timeAry = null;
                    }
                });
                minTime += Math.floor(secTime / 60);
                secTime = Math.floor(secTime % 60);
            }
            // if ((minTime + secTime) > 0)
            //   self.irrigationHistoryTime = "";
            //if (minTime > 0)
            self.irrigationHistoryTime = minTime.toString() + self.translate.get("common.min")["value"] + " ";
            //if (secTime > 0)
            self.irrigationHistoryTime += secTime.toString() + self.translate.get("common.sec")["value"];
        });
    };
    TwoSchedulePage.prototype.getTimePatch = function (num) {
        if (num) {
            if (typeof (num) == "number") {
                if (num < 0)
                    return num.toString();
                else if (num >= 0 && num < 10)
                    return "0" + num.toString();
                else if (num >= 10)
                    return num.toString();
                else
                    return "00".toString();
            }
            else if (typeof (num) == "string") {
                if (parseInt(num) < 0)
                    return num;
                else if (parseInt(num) >= 0 && parseInt(num) < 10)
                    return "0" + num;
                else if (parseInt(num) >= 10)
                    return num.toString();
                else
                    return num;
            }
            else
                return num;
        }
        else {
            return "00";
        }
    };
    TwoSchedulePage.prototype.goBack = function () {
        this.navCtrl.pop();
    };
