    //保存
    WateringDayTwoPage.prototype.saveData = function () {
        var self = this;
        if (self.switchIndex == 2) {
            localStorage.setItem("zm_interval_zone" + self.siteIndex + "_switch" + self.wIndex, JSON.stringify({
                zcmInterval1: self.zcmInterval1,
                zcmInterval2: self.zcmInterval2,
                createTime: new Date().getTime()
            }));
        }
        //定时模式
        if (self.wIndex == 1) {
            //天模式
            if (self.switchIndex == 1) {
                self.timeDayChoice();
            } //间隔模式
            else if (self.switchIndex == 2) {
                self.timeZcmIntervalChoice();
            } //ODD/EVEN模式
            else if (self.switchIndex == 8) {
                self.timeOddEvenChoice();
            }
        } //循环模式
        else if (self.wIndex == 2) {
            //天模式
            if (self.switchIndex == 1) {
                self.cycDayChoice();
            } //间隔模式
            else if (self.switchIndex == 2) {
                self.cycZcmIntervalChoice();
            } //ODD/EVEN模式
            else if (self.switchIndex == 8) {
                self.cycOddEvenChoice();
            }
        }
    };
