                                var startTime = new Date(tmpDate.getFullYear() + '-' + (tmpDate.getMonth() + 1) + '-' + tmpDate.getDate() + " " + time.start + ":00");
                                var endTime = new Date(tmpDate.getFullYear() + '-' + (tmpDate.getMonth() + 1) + '-' + tmpDate.getDate() + " " + time.end + ":00");
                                var tmpDate1 = startTime;
